func registerIcons() {
	for name, path := range icons {
		icon.Register(name, icon.Path{Data: path})
	}
}

// ic renders a registered icon as a square of size dp in color.
func ic(name string, size int, color string) elements.Element {
	return icon.Named(name, styles.Styles{Width: properties.Width(size), Height: properties.Height(size), Color: color})
}

// src returns a registered icon as an icon.Source, for menus.
func src(name string) icon.Source {
	s, ok := icon.Lookup(name)
	if !ok {
		s, _ = icon.Lookup("blank")
	}
	return s
}
